CREATE TABLE IF NOT EXISTS src_crm.crm_contract(id BIGINT AUTO_INCREMENT PRIMARY KEY,contract_no VARCHAR(32) NOT NULL,version_no INT NOT NULL DEFAULT 1,contract_name VARCHAR(200) NOT NULL,quotation_id BIGINT,quotation_no VARCHAR(32),opportunity_no VARCHAR(32),customer_code VARCHAR(32) NOT NULL,customer_name VARCHAR(200),amount DECIMAL(18,2) NOT NULL,tax_amount DECIMAL(18,2) DEFAULT 0,currency VARCHAR(8) DEFAULT 'CNY',effective_date DATE,expire_date DATE,delivery_terms VARCHAR(500),payment_terms VARCHAR(500),penalty_terms VARCHAR(500),attachment_name VARCHAR(255),status VARCHAR(20) DEFAULT 'DRAFT',workflow_instance_id BIGINT,erp_sales_order_no VARCHAR(32),created_by VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),UNIQUE KEY uk_contract_version(contract_no,version_no));
CREATE TABLE IF NOT EXISTS src_crm.crm_payment_plan(id BIGINT AUTO_INCREMENT PRIMARY KEY,contract_id BIGINT NOT NULL,period_no INT NOT NULL,due_date DATE NOT NULL,plan_ratio DECIMAL(8,4),plan_amount DECIMAL(18,2) NOT NULL,received_amount DECIMAL(18,2) DEFAULT 0,status VARCHAR(16) DEFAULT 'PLANNED',UNIQUE KEY uk_contract_period(contract_id,period_no));
CREATE TABLE IF NOT EXISTS src_crm.crm_contract_change(id BIGINT AUTO_INCREMENT PRIMARY KEY,contract_id BIGINT NOT NULL,from_version INT NOT NULL,to_version INT NOT NULL,change_reason VARCHAR(500) NOT NULL,changed_by VARCHAR(32),changed_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
